insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'CONSTITUCION_SOCIEDADES', 'GENERAL', 'permitido',
         null, null,
         '["Constituirse ante fedatario publico (notario o corredor publico) — Art. 5o", "La escritura/poliza debe contener los requisitos del Art. 6o (nombres de socios, objeto, denominacion, duracion, capital y aportaciones, domicilio, forma de administracion y facultades, nombramiento de administradores, reparto de utilidades, fondo de reserva)", "Inscribir la sociedad en el Registro Publico de Comercio para tener personalidad juridica plena y evitar el regimen de sociedad irregular (Art. 2o)"]'::jsonb, '["Sociedad irregular (no inscrita): quienes realicen actos juridicos en su nombre responden subsidiaria, solidaria e ilimitadamente frente a terceros", "La SAS NO se constituye por esta via: tiene procedimiento electronico propio (Capitulo XIV, ver categoria SAS_CONSTITUCION)"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-LGSM-5-6-CONSTITUCION'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-LGSM-260-263-SAS', 'MX', 'regulatorio', 'SAS: constitucion electronica, solo personas fisicas y tope de ingresos anuales', 'La sociedad por acciones simplificada se constituye con una o mas PERSONAS FISICAS (una persona moral no puede ser accionista), mediante el sistema electronico de la Secretaria de Economia (Art. 263). Los ingresos totales anuales no pueden rebasar $7,678,849.94 (cantidad ACTUALIZADA por Acuerdo DOF 26-12-2025; se actualiza cada 1 de enero); si se rebasa, la SAS debe transformarse en otro regimen societario (Art. 260). Un accionista de SAS no puede ser simultaneamente accionista de control de otra sociedad mercantil (Art. 260 en relacion con el Art. 2 fr. III de la Ley del Mercado de Valores). La SAS esta exceptuada de la reserva legal (Art. 20).',
   'LGSM, Arts. 260 a 263 (SAS adicionada DOF 14-03-2016; tope actualizado por Acuerdo DOF 26-12-2025) y Art. 20', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LGSM.pdf', 'seed v4 2026-07-30 — LISR/CFF (MX), ET (CO), NIF CINIF, CCF/CCom (MX); verificar contra fuente oficial (DOF/DIAN) antes de produccion; regulatorio MX 2026-07: Ley de Aviacion Civil (reforma consolidada DOF 14-11-2025) + NOM-107-SCT3-2019, Ley de Instituciones de Seguros y de Fianzas (texto vigente DOF 14-11-2025, Art. 91/93/94 sin evidencia de reforma posterior a su publicacion original DOF 04-04-2013) — verificado contra texto primario, no contra blogs de terceros. Fase 8b (2026-07-10): categoria AGENTES_SEGUROS + exclusiones en el clasificador para que no colisione con DRONES_DELIVERY (incidente real en #dep-legal). datos-personales MX 2026-07-30: LFPDPPP NUEVA LEY (publicada DOF 20-03-2025, vigente 21-03-2025, texto vigente con ultima reforma DOF 14-11-2025; la ley de 2010 quedo ABROGADA por el Transitorio Segundo del Decreto; autoridad de proteccion de datos: Secretaria Anticorrupcion y Buen Gobierno — INAI extinto, Art. 3 fraccion XV). Arts. 3-X, 5, 6, 9-II, 14, 15, 16, 17, 20, 35 y 36 verificados contra el PDF oficial de Diputados (LeyesBiblio), no contra blogs. La regla MX-LFPDPPP-21-CONFIDENCIALIDAD (ley 2010) se retira via _bajas y la sustituye MX-LFPDPPP2025-20-CONFIDENCIALIDAD. corporativo-mercantil MX 2026-08-06 (Fase A): LGSM texto vigente (ultima reforma DOF 20-10-2023, cantidades actualizadas por Acuerdo DOF 26-12-2025 — tope SAS $7,678,849.94 leido del PDF oficial), CFF (ultima reforma DOF 09-04-2026, Arts. 32-B Ter/84-M cotejados) y LFCE (ultima reforma DOF 14-11-2025; umbrales del Art. 86 REFORMADOS DOF 16-07-2025 a 16M/30%+16M/7.4M+40M UMA, leidos del PDF oficial — los umbrales pre-reforma 18M/48M/8.4M quedan obsoletos). Arts. 2, 5, 6, 10, 19, 20, 128, 129, 178, 180-182, 186, 222-225, 228 Bis y 260-263 LGSM verificados contra el PDF de Diputados (LeyesBiblio), no contra blogs ni memoria. fiduciario/sucesorio/inmobiliario MX 2026-08-07 (Fase B): LGTOC texto vigente (ultima reforma DOF 26-03-2024, Arts. 381-394 cotejados — prohibiciones del 394 incl. limite de 50 anos con excepcion de museos), CCF (ultima reforma DOF 14-11-2025, Arts. 1295-1296/1500-1501/1511, 1599/1602, 2317/2320 con umbral de 365 salarios minimos pendiente de conversion UMA, 3007-3009) y LIE (ultima reforma DOF 27-05-2024, Arts. 2-VI y 10-14: zona restringida 100/50 km, fideicomiso 50 anos prorrogable, permiso SRE). Todo leido de los PDF de Diputados (LeyesBiblio), no de memoria. Bandera transversal: la materia civil es LOCAL — el CCF es referencia federal, cotejar el codigo del estado. ambiental MX 2026-08-07 (Fase C): LGEEPA texto vigente (ultima reforma DOF 19-01-2026, Arts. 28/30 EIA con las 10 fracciones leidas del PDF, 38-38 Bis auditoria voluntaria, 111 Bis fuentes fijas federales con su lista de industrias), LGPGIR (ultima reforma DOF 19-01-2026, categorias de generador del Art. 5 fr. XII/XIX/XX: micro <=400 kg/ano, pequeno 400 kg-<10 t, gran >=10 t; Arts. 42/44/46) y LFRA (ultima reforma DOF 14-11-2025, Arts. 1o/10: reparacion prioritaria, compensacion subsidiaria, responsabilidad por dano indirecto). Todo leido de los PDF de Diputados (LeyesBiblio). El veredicto de RESPONSABILIDAD_AMBIENTAL es no_permitido (ocasionar dano ambiental genera responsabilidad objetiva), unico en su categoria — sin conflicto de veredictos. cabildeo/politico MX 2026-08-07 (Fase D): Reglamento de la Camara de Diputados (ultima reforma DOF 07-05-2025, Arts. 263-268: registro por legislatura, cupos 20 por comision / 2 por persona moral, veto a servidores publicos y parientes 4o grado, archivo publico), Reglamento del Senado (ultima reforma DOF 06-12-2024, Arts. 298-299: informes a la Mesa, sin dadivas), LGPP (ultima reforma DOF 02-03-2023, Art. 54-1-f/g: personas morales y residentes en el extranjero NO aportan — con la nota de la sentencia SCJN DOF 24-11-2023 sobre incisos reformados) y LGIPE (ultima reforma DOF 02-06-2026, Art. 159-4/5: prohibida la contratacion de propaganda en radio/TV por cualquier persona fisica o moral). Todo leido de los PDF de Diputados. Los dos no_permitido (aportaciones, propaganda) van unicos en su categoria — sin conflicto de veredictos (leccion Fase B). frontera financiera MX 2026-08-07 (dictamen Financial Consulting): LMV texto vigente (ultima reforma DOF 14-11-2025), Arts. 225 (definicion y registro CNBV; parrafo de personas morales reformado DOF 28-12-2023: SC/SA/S de RL con objeto y establecimientos exclusivos), 226 y 227 Bis, leidos del PDF de Diputados. La consultoria financiera general NO es reservada; el gatillo es habitual+profesional+valores+individualizada. Dictamen completo en grafo/DICTAMEN-FRONTERA-FINANCIAL-CONSULTING.md. propiedad industrial MX 2026-08-08: LFPPI (nueva ley DOF 01-07-2020, en vigor 05-11-2020 por su Transitorio PRIMERO —90 dias habiles, computados—; texto vigente ultima reforma DOF 03-04-2026). Arts. 53, 62, 78, 79, 87, 170, 174, 178, 204, 233, 235, 236, 237, 238 y Transitorio DECIMO PRIMERO leidos del PDF oficial de Diputados (LeyesBiblio), no de memoria. Los tres impactos son ''permitido'' y las dos categorias son nuevas — sin conflicto de veredictos. vocabulario 2026-08-08: se amplian keywords de TESTAMENTOS_SUCESIONES e COMPRAVENTA_INMUEBLES con formas derivadas y traducciones EQUIVALENTES (plural/genero y ''property law''), porque la frontera de palabra rechazaba ''juicios sucesorios'' teniendo ''juicio sucesorio'', e ''inmobiliario'' teniendo ''inmueble''. NO se anaden etiquetas amplias de area de practica (''derecho corporativo'', ''environmental consulting''): abarcan varias categorias y el clasificador devuelve UNA — forzarlas daria un dictamen seguro de si mismo sobre una pregunta que nadie hizo. Ademas ''inmueble''/''inmuebles'' a secas: el sitio de un despacho dice ''Abogados Especialistas En Inmuebles'' y solo existian las formas compuestas (''bien inmueble''). servicios legales transversal 2026-08-08: categoria SERVICIOS_LEGALES (operar como despacho — transversal, NO area de practica: las areas siguen en sus categorias propias conforme a la doctrina del vocabulario 2026-08-08) + Ley Reglamentaria del Art. 5o. Constitucional CDMX (texto vigente, ultima reforma DOF 19-01-2018), Arts. 24/25/26 leidos del PDF oficial de Diputados (pdf_mov), con bandera de materia LOCAL; + LFPIORPI (texto vigente, ultima reforma DOF 16-07-2025), Arts. 17-XI (incisos a-e y parrafo de Aviso) y 18 (fracciones I-III) y Transitorio Primero (vigor a los nueve meses de la publicacion del 17-10-2012 = 2013-07-17) leidos del PDF oficial, no de memoria. Ambos impactos ''permitido'' sobre la misma categoria — sin conflicto de veredictos. Keyword ''de legal'' (NO ''legal'' desnuda: el ataque adversarial 2026-08-08 mostro que ''legal'' adjetival sobre-clasifica — ''capacidad legal'', ''domicilio legal'', ''validez legal del contrato'' recibirian dictamen de despacho; el uso SUSTANTIVO de la practica legal casi siempre viene como ''de legal'', que es el patron del concepto del pre-discovery ''Operacion de Legal en Mexico''), mas exclusiones de bigramas adjetivales frecuentes; ''abogado'' y ''notario'' singulares quedan en SERVICIOS_PROFESIONALES (fiscal) por unicidad global de keywords. vigente_desde de LRArt5 = 2018-01-19 (fecha de la ultima reforma del texto citado — el parrafo primero del Art. 25 fue reformado DOF 19-01-2018; mismo criterio que la regla de la Ley de Aviacion Civil), lo que ademas hace rectora del dictamen a la regla de titulo profesional (la barrera universal), no a la de lavado. comercio exterior MX 2026-09-02: Ley Aduanera (texto vigente, ultima reforma DOF 19-11-2025, Ley publicada DOF 15-12-1995 y en vigor el 01-01-1996 por su Transitorio Primero) y Ley de Comercio Exterior (texto vigente, ultima reforma DOF 01-05-2026, Ley publicada DOF 27-07-1993 y en vigor al dia siguiente). Arts. 36-A, 40, 59, 64, 90 y 176 de la Ley Aduanera y Arts. 15, 16, 17, 21, 23, 24, 26, 28, 62 y 63 de la Ley de Comercio Exterior leidos del PDF oficial de Diputados (LeyesBiblio) extraido con pypdf, no de memoria ni de resumenes: el indice HTML del sitio daba 27-12-2025 como ultima reforma de la Ley Aduanera, pero esa fecha es la actualizacion de cantidades por Reglas Generales de Comercio Exterior y el texto vigente es DOF 19-11-2025. Dos veredictos son dudoso por fail-safe declarado: CLASIFICACION_ARANCELARIA (la Tarifa de la LIGIE no esta sembrada) y PRACTICAS_DESLEALES (la resolucion de cuota compensatoria por producto y origen vive en el DOF, no aqui). INFRACCIONES_ADUANERAS es la unica categoria con veredicto no_permitido y va sola en su categoria, sin conflicto de veredictos (leccion Fase B). Fuera de alcance a proposito: Reglas Generales de Comercio Exterior (cambian cada ano), Tarifa de la LIGIE, reglas de origen de los tratados y jurisdicciones extranjeras. logistica MX 2026-09-02: Ley de Caminos, Puentes y Autotransporte Federal (texto vigente, ultima reforma DOF 14-11-2025, Ley publicada DOF 22-12-1993 y en vigor al dia siguiente) y Ley de Aviacion Civil (texto vigente, ultima reforma DOF 14-11-2025, publicada DOF 12-05-1995 y en vigor al dia siguiente), Arts. 8o./50/66/68 LCPAF y 11/55/56 LAC leidos del PDF oficial de Diputados con pypdf. Cierran las dos categorias que el escaneo regulatorio del Pre-Discovery esperaba y el seed no tenia (AUTOTRANSPORTE_CARGA y CARGA_AEREA_EAWB), cuyo mock las dictaminaba con fuente IATA sin anclaje nacional. La base mexicana de la guia aerea es el Art. 55 LAC —el contrato DEBE constar en carta de porte o guia de carga aerea— y el formato lo fija una NOM que NO esta sembrada: por eso la forma ELECTRONICA (e-AWB) queda como bandera y la Resolucion 672 de IATA se declara estandar sectorial, no exigencia de autoridad. Fuera de alcance: reglamentos de materiales peligrosos, la NOM del formato de la guia, el Convenio de Montreal y las Reglas Generales de Comercio Exterior. T-MEC 2026-09-03: textos finales del Tratado entre Mexico, Estados Unidos y Canada publicados por la Secretaria de Economia (gob.mx), promulgado por decreto DOF 29-06-2020 y en vigor el 01-07-2020. Capitulo 4 (Reglas de Origen), Capitulo 5 (Procedimientos de Origen) y Capitulo 7 (Administracion Aduanera y Facilitacion del Comercio) leidos de los PDF oficiales con pypdf, no de memoria ni de resumenes: la numeracion real desmiente la de los blogs (5.2 es Solicitudes de Trato Preferencial, 5.3 Bases de la Certificacion, 5.5 Excepciones y 5.11 Devoluciones; no la del TLCAN). Seis categorias nuevas TMEC_* mas un impacto del Art. 7.20 en la categoria existente REPRESENTACION_ADUANAL. Convencion de veredictos respetada: una sola regla rectora por categoria y las complementarias con veredicto_base null (solo aportan requisitos, banderas y fuente), porque el motor reporta CONTRADICCION cuando dos veredictos distintos viven en la misma categoria. Dos veredictos dudoso por fail-safe declarado: TMEC_REGLAS_ORIGEN (el Anexo 4-B, reglas especificas por producto, NO esta sembrado, de modo que el grafo no puede decir si una mercancia concreta califica) y TMEC_ENVIOS_ENTREGA_RAPIDA (el Art. 7.8 obliga a Mexico a un PISO de 117 USD para aranceles y 50 USD para impuestos, pero lo que paga un envio concreto lo fija el ordenamiento domestico vigente, que cambia). Fuera de alcance a proposito: Anexo 4-B y su apendice automotriz, Capitulo 6 (textiles), Reglamentaciones Uniformes, Reglas Generales de Comercio Exterior y los demas tratados de los que Mexico es parte.',
   '2016-03-14'::date, null)
  on conflict (clave) do update set jurisdiccion = excluded.jurisdiccion,
    dimension = excluded.dimension, titulo = excluded.titulo,
    texto_resumen = excluded.texto_resumen, fuente_cita = excluded.fuente_cita,
    fuente_url = excluded.fuente_url, source_version = excluded.source_version,
    vigente_desde = excluded.vigente_desde, vigente_hasta = excluded.vigente_hasta;
insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'SAS_CONSTITUCION', 'GENERAL', 'permitido',
         null, null,
         '["Todos los accionistas deben ser personas fisicas obligadas solo al pago de sus aportaciones (Art. 260)", "Constituirse por el sistema electronico de la Secretaria de Economia conforme a sus reglas generales (Art. 263)", "Vigilar el tope de ingresos totales anuales; al rebasarlo, transformarse en otro tipo societario (Art. 260, segundo parrafo)", "Verificar que ningun accionista tenga control simultaneo de otra sociedad mercantil (Art. 260 primer parrafo)"]'::jsonb, '["NO apta como vehiculo de holding: las personas morales no pueden ser accionistas de una SAS", "El tope se actualiza cada 1 de enero (factor de actualizacion): cotejar el Acuerdo vigente en DOF antes de asesorar", "La vacatio legis de la reforma que creo la SAS (DOF 14-03-2016) fue de 6 meses: entrada en vigor operativa posterior a la publicacion — cotejar transitorios"]'::jsonb, '{"tope_ingresos_anuales_mxn": 7678849.94, "verificar": true}'::jsonb
  from reglas r where r.clave = 'MX-LGSM-260-263-SAS'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-LGSM-178-182-ASAMBLEAS', 'MX', 'regulatorio', 'Asamblea de accionistas: organo supremo y asamblea ordinaria anual obligatoria', 'La Asamblea General de Accionistas es el organo supremo de la sociedad (Art. 178); los estatutos pueden prever resoluciones fuera de asamblea por unanimidad con la misma validez. Son ordinarias las asambleas que tratan asuntos distintos de los del Art. 182 (Art. 180). La Asamblea Ordinaria debe reunirse al menos una vez al ano dentro de los CUATRO MESES siguientes a la clausura del ejercicio social, para discutir/aprobar el informe de los administradores (con el informe del comisario), nombrar administradores y comisarios y determinar sus emolumentos (Art. 181). Los asuntos del Art. 182 (reformas de estatutos, fusion, escision, etc.) exigen asamblea extraordinaria.',
   'LGSM, Arts. 178, 180, 181 y 182 (texto vigente, ultima reforma DOF 20-10-2023)', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LGSM.pdf', 'seed v4 2026-07-30 — LISR/CFF (MX), ET (CO), NIF CINIF, CCF/CCom (MX); verificar contra fuente oficial (DOF/DIAN) antes de produccion; regulatorio MX 2026-07: Ley de Aviacion Civil (reforma consolidada DOF 14-11-2025) + NOM-107-SCT3-2019, Ley de Instituciones de Seguros y de Fianzas (texto vigente DOF 14-11-2025, Art. 91/93/94 sin evidencia de reforma posterior a su publicacion original DOF 04-04-2013) — verificado contra texto primario, no contra blogs de terceros. Fase 8b (2026-07-10): categoria AGENTES_SEGUROS + exclusiones en el clasificador para que no colisione con DRONES_DELIVERY (incidente real en #dep-legal). datos-personales MX 2026-07-30: LFPDPPP NUEVA LEY (publicada DOF 20-03-2025, vigente 21-03-2025, texto vigente con ultima reforma DOF 14-11-2025; la ley de 2010 quedo ABROGADA por el Transitorio Segundo del Decreto; autoridad de proteccion de datos: Secretaria Anticorrupcion y Buen Gobierno — INAI extinto, Art. 3 fraccion XV). Arts. 3-X, 5, 6, 9-II, 14, 15, 16, 17, 20, 35 y 36 verificados contra el PDF oficial de Diputados (LeyesBiblio), no contra blogs. La regla MX-LFPDPPP-21-CONFIDENCIALIDAD (ley 2010) se retira via _bajas y la sustituye MX-LFPDPPP2025-20-CONFIDENCIALIDAD. corporativo-mercantil MX 2026-08-06 (Fase A): LGSM texto vigente (ultima reforma DOF 20-10-2023, cantidades actualizadas por Acuerdo DOF 26-12-2025 — tope SAS $7,678,849.94 leido del PDF oficial), CFF (ultima reforma DOF 09-04-2026, Arts. 32-B Ter/84-M cotejados) y LFCE (ultima reforma DOF 14-11-2025; umbrales del Art. 86 REFORMADOS DOF 16-07-2025 a 16M/30%+16M/7.4M+40M UMA, leidos del PDF oficial — los umbrales pre-reforma 18M/48M/8.4M quedan obsoletos). Arts. 2, 5, 6, 10, 19, 20, 128, 129, 178, 180-182, 186, 222-225, 228 Bis y 260-263 LGSM verificados contra el PDF de Diputados (LeyesBiblio), no contra blogs ni memoria. fiduciario/sucesorio/inmobiliario MX 2026-08-07 (Fase B): LGTOC texto vigente (ultima reforma DOF 26-03-2024, Arts. 381-394 cotejados — prohibiciones del 394 incl. limite de 50 anos con excepcion de museos), CCF (ultima reforma DOF 14-11-2025, Arts. 1295-1296/1500-1501/1511, 1599/1602, 2317/2320 con umbral de 365 salarios minimos pendiente de conversion UMA, 3007-3009) y LIE (ultima reforma DOF 27-05-2024, Arts. 2-VI y 10-14: zona restringida 100/50 km, fideicomiso 50 anos prorrogable, permiso SRE). Todo leido de los PDF de Diputados (LeyesBiblio), no de memoria. Bandera transversal: la materia civil es LOCAL — el CCF es referencia federal, cotejar el codigo del estado. ambiental MX 2026-08-07 (Fase C): LGEEPA texto vigente (ultima reforma DOF 19-01-2026, Arts. 28/30 EIA con las 10 fracciones leidas del PDF, 38-38 Bis auditoria voluntaria, 111 Bis fuentes fijas federales con su lista de industrias), LGPGIR (ultima reforma DOF 19-01-2026, categorias de generador del Art. 5 fr. XII/XIX/XX: micro <=400 kg/ano, pequeno 400 kg-<10 t, gran >=10 t; Arts. 42/44/46) y LFRA (ultima reforma DOF 14-11-2025, Arts. 1o/10: reparacion prioritaria, compensacion subsidiaria, responsabilidad por dano indirecto). Todo leido de los PDF de Diputados (LeyesBiblio). El veredicto de RESPONSABILIDAD_AMBIENTAL es no_permitido (ocasionar dano ambiental genera responsabilidad objetiva), unico en su categoria — sin conflicto de veredictos. cabildeo/politico MX 2026-08-07 (Fase D): Reglamento de la Camara de Diputados (ultima reforma DOF 07-05-2025, Arts. 263-268: registro por legislatura, cupos 20 por comision / 2 por persona moral, veto a servidores publicos y parientes 4o grado, archivo publico), Reglamento del Senado (ultima reforma DOF 06-12-2024, Arts. 298-299: informes a la Mesa, sin dadivas), LGPP (ultima reforma DOF 02-03-2023, Art. 54-1-f/g: personas morales y residentes en el extranjero NO aportan — con la nota de la sentencia SCJN DOF 24-11-2023 sobre incisos reformados) y LGIPE (ultima reforma DOF 02-06-2026, Art. 159-4/5: prohibida la contratacion de propaganda en radio/TV por cualquier persona fisica o moral). Todo leido de los PDF de Diputados. Los dos no_permitido (aportaciones, propaganda) van unicos en su categoria — sin conflicto de veredictos (leccion Fase B). frontera financiera MX 2026-08-07 (dictamen Financial Consulting): LMV texto vigente (ultima reforma DOF 14-11-2025), Arts. 225 (definicion y registro CNBV; parrafo de personas morales reformado DOF 28-12-2023: SC/SA/S de RL con objeto y establecimientos exclusivos), 226 y 227 Bis, leidos del PDF de Diputados. La consultoria financiera general NO es reservada; el gatillo es habitual+profesional+valores+individualizada. Dictamen completo en grafo/DICTAMEN-FRONTERA-FINANCIAL-CONSULTING.md. propiedad industrial MX 2026-08-08: LFPPI (nueva ley DOF 01-07-2020, en vigor 05-11-2020 por su Transitorio PRIMERO —90 dias habiles, computados—; texto vigente ultima reforma DOF 03-04-2026). Arts. 53, 62, 78, 79, 87, 170, 174, 178, 204, 233, 235, 236, 237, 238 y Transitorio DECIMO PRIMERO leidos del PDF oficial de Diputados (LeyesBiblio), no de memoria. Los tres impactos son ''permitido'' y las dos categorias son nuevas — sin conflicto de veredictos. vocabulario 2026-08-08: se amplian keywords de TESTAMENTOS_SUCESIONES e COMPRAVENTA_INMUEBLES con formas derivadas y traducciones EQUIVALENTES (plural/genero y ''property law''), porque la frontera de palabra rechazaba ''juicios sucesorios'' teniendo ''juicio sucesorio'', e ''inmobiliario'' teniendo ''inmueble''. NO se anaden etiquetas amplias de area de practica (''derecho corporativo'', ''environmental consulting''): abarcan varias categorias y el clasificador devuelve UNA — forzarlas daria un dictamen seguro de si mismo sobre una pregunta que nadie hizo. Ademas ''inmueble''/''inmuebles'' a secas: el sitio de un despacho dice ''Abogados Especialistas En Inmuebles'' y solo existian las formas compuestas (''bien inmueble''). servicios legales transversal 2026-08-08: categoria SERVICIOS_LEGALES (operar como despacho — transversal, NO area de practica: las areas siguen en sus categorias propias conforme a la doctrina del vocabulario 2026-08-08) + Ley Reglamentaria del Art. 5o. Constitucional CDMX (texto vigente, ultima reforma DOF 19-01-2018), Arts. 24/25/26 leidos del PDF oficial de Diputados (pdf_mov), con bandera de materia LOCAL; + LFPIORPI (texto vigente, ultima reforma DOF 16-07-2025), Arts. 17-XI (incisos a-e y parrafo de Aviso) y 18 (fracciones I-III) y Transitorio Primero (vigor a los nueve meses de la publicacion del 17-10-2012 = 2013-07-17) leidos del PDF oficial, no de memoria. Ambos impactos ''permitido'' sobre la misma categoria — sin conflicto de veredictos. Keyword ''de legal'' (NO ''legal'' desnuda: el ataque adversarial 2026-08-08 mostro que ''legal'' adjetival sobre-clasifica — ''capacidad legal'', ''domicilio legal'', ''validez legal del contrato'' recibirian dictamen de despacho; el uso SUSTANTIVO de la practica legal casi siempre viene como ''de legal'', que es el patron del concepto del pre-discovery ''Operacion de Legal en Mexico''), mas exclusiones de bigramas adjetivales frecuentes; ''abogado'' y ''notario'' singulares quedan en SERVICIOS_PROFESIONALES (fiscal) por unicidad global de keywords. vigente_desde de LRArt5 = 2018-01-19 (fecha de la ultima reforma del texto citado — el parrafo primero del Art. 25 fue reformado DOF 19-01-2018; mismo criterio que la regla de la Ley de Aviacion Civil), lo que ademas hace rectora del dictamen a la regla de titulo profesional (la barrera universal), no a la de lavado. comercio exterior MX 2026-09-02: Ley Aduanera (texto vigente, ultima reforma DOF 19-11-2025, Ley publicada DOF 15-12-1995 y en vigor el 01-01-1996 por su Transitorio Primero) y Ley de Comercio Exterior (texto vigente, ultima reforma DOF 01-05-2026, Ley publicada DOF 27-07-1993 y en vigor al dia siguiente). Arts. 36-A, 40, 59, 64, 90 y 176 de la Ley Aduanera y Arts. 15, 16, 17, 21, 23, 24, 26, 28, 62 y 63 de la Ley de Comercio Exterior leidos del PDF oficial de Diputados (LeyesBiblio) extraido con pypdf, no de memoria ni de resumenes: el indice HTML del sitio daba 27-12-2025 como ultima reforma de la Ley Aduanera, pero esa fecha es la actualizacion de cantidades por Reglas Generales de Comercio Exterior y el texto vigente es DOF 19-11-2025. Dos veredictos son dudoso por fail-safe declarado: CLASIFICACION_ARANCELARIA (la Tarifa de la LIGIE no esta sembrada) y PRACTICAS_DESLEALES (la resolucion de cuota compensatoria por producto y origen vive en el DOF, no aqui). INFRACCIONES_ADUANERAS es la unica categoria con veredicto no_permitido y va sola en su categoria, sin conflicto de veredictos (leccion Fase B). Fuera de alcance a proposito: Reglas Generales de Comercio Exterior (cambian cada ano), Tarifa de la LIGIE, reglas de origen de los tratados y jurisdicciones extranjeras. logistica MX 2026-09-02: Ley de Caminos, Puentes y Autotransporte Federal (texto vigente, ultima reforma DOF 14-11-2025, Ley publicada DOF 22-12-1993 y en vigor al dia siguiente) y Ley de Aviacion Civil (texto vigente, ultima reforma DOF 14-11-2025, publicada DOF 12-05-1995 y en vigor al dia siguiente), Arts. 8o./50/66/68 LCPAF y 11/55/56 LAC leidos del PDF oficial de Diputados con pypdf. Cierran las dos categorias que el escaneo regulatorio del Pre-Discovery esperaba y el seed no tenia (AUTOTRANSPORTE_CARGA y CARGA_AEREA_EAWB), cuyo mock las dictaminaba con fuente IATA sin anclaje nacional. La base mexicana de la guia aerea es el Art. 55 LAC —el contrato DEBE constar en carta de porte o guia de carga aerea— y el formato lo fija una NOM que NO esta sembrada: por eso la forma ELECTRONICA (e-AWB) queda como bandera y la Resolucion 672 de IATA se declara estandar sectorial, no exigencia de autoridad. Fuera de alcance: reglamentos de materiales peligrosos, la NOM del formato de la guia, el Convenio de Montreal y las Reglas Generales de Comercio Exterior. T-MEC 2026-09-03: textos finales del Tratado entre Mexico, Estados Unidos y Canada publicados por la Secretaria de Economia (gob.mx), promulgado por decreto DOF 29-06-2020 y en vigor el 01-07-2020. Capitulo 4 (Reglas de Origen), Capitulo 5 (Procedimientos de Origen) y Capitulo 7 (Administracion Aduanera y Facilitacion del Comercio) leidos de los PDF oficiales con pypdf, no de memoria ni de resumenes: la numeracion real desmiente la de los blogs (5.2 es Solicitudes de Trato Preferencial, 5.3 Bases de la Certificacion, 5.5 Excepciones y 5.11 Devoluciones; no la del TLCAN). Seis categorias nuevas TMEC_* mas un impacto del Art. 7.20 en la categoria existente REPRESENTACION_ADUANAL. Convencion de veredictos respetada: una sola regla rectora por categoria y las complementarias con veredicto_base null (solo aportan requisitos, banderas y fuente), porque el motor reporta CONTRADICCION cuando dos veredictos distintos viven en la misma categoria. Dos veredictos dudoso por fail-safe declarado: TMEC_REGLAS_ORIGEN (el Anexo 4-B, reglas especificas por producto, NO esta sembrado, de modo que el grafo no puede decir si una mercancia concreta califica) y TMEC_ENVIOS_ENTREGA_RAPIDA (el Art. 7.8 obliga a Mexico a un PISO de 117 USD para aranceles y 50 USD para impuestos, pero lo que paga un envio concreto lo fija el ordenamiento domestico vigente, que cambia). Fuera de alcance a proposito: Anexo 4-B y su apendice automotriz, Capitulo 6 (textiles), Reglamentaciones Uniformes, Reglas Generales de Comercio Exterior y los demas tratados de los que Mexico es parte.',
   '1934-08-04'::date, null)
  on conflict (clave) do update set jurisdiccion = excluded.jurisdiccion,
    dimension = excluded.dimension, titulo = excluded.titulo,
    texto_resumen = excluded.texto_resumen, fuente_cita = excluded.fuente_cita,
    fuente_url = excluded.fuente_url, source_version = excluded.source_version,
    vigente_desde = excluded.vigente_desde, vigente_hasta = excluded.vigente_hasta;
insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'ASAMBLEAS_SOCIETARIAS', 'GENERAL', 'permitido',
         null, null,
         '["Celebrar la asamblea ordinaria anual dentro de los 4 meses posteriores al cierre del ejercicio (Art. 181)", "En la ordinaria anual: discutir/aprobar/modificar el informe de los administradores tomando en cuenta el del comisario, nombrar administradores y comisarios y fijar emolumentos (Art. 181, fracciones I-III)", "Tratar los asuntos del Art. 182 (reforma de estatutos, fusion, escision, cambio de objeto, etc.) SOLO en asamblea extraordinaria"]'::jsonb, '["Resoluciones fuera de asamblea: validas solo si los estatutos lo preven y son por unanimidad de quienes representan la totalidad de las acciones con derecho a voto (Art. 178)"]'::jsonb, '{"plazo_meses_asamblea_anual": 4, "verificar": true}'::jsonb
  from reglas r where r.clave = 'MX-LGSM-178-182-ASAMBLEAS'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

