insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'TESTAMENTOS_SUCESIONES', 'GENERAL', 'permitido',
         null, null,
         '["Verificar el supuesto de apertura de la sucesion legitima (Art. 1599) antes de tramitar el intestado", "Determinar el orden de herederos aplicable (Art. 1602 y reglas del titulo respectivo)", "Concubina/concubinario: acreditar los requisitos del Art. 1635"]'::jsonb, '["La materia civil (sucesiones e inmuebles) es competencia LOCAL: el CCF es la referencia federal; cotejar el codigo civil y la ley registral del estado donde este el bien o se abra la sucesion", "En patrimonios con sociedades (holding familiar): la transmision de acciones por herencia detona ademas registro de acciones (LGSM 128-129) y beneficiario controlador (CFF 32-B Ter)"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-CCF-1599-1602-SUCESION-LEGITIMA'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
