insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'TMEC_CERTIFICACION_ORIGEN', 'GENERAL', null,
         null, null,
         '["Ante un requerimiento por certificacion ilegible o defectuosa, presentar copia corregida dentro del plazo concedido, que no puede ser menor a cinco dias habiles (Art. 5.7.2)", "Documentar que el error es menor y que no afecta la exactitud de la documentacion de importacion, para invocar el Art. 5.7.1"]'::jsonb, '["Un error de captura no justifica por si solo negar la preferencia arancelaria (Art. 5.7.1): es un argumento oponible ante la autoridad", "El plazo de cinco dias habiles es un PISO del tratado; la autoridad mexicana puede conceder mas, no menos"]'::jsonb, '{"plazo_correccion_dias_habiles": 5, "verificar": true}'::jsonb
  from reglas r where r.clave = 'MX-TMEC-5.7-ERRORES-DISCREPANCIAS'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
