insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'REPRESENTACION_ADUANAL', 'GENERAL', null,
         null, null,
         '["Si se opta por auto-declarar, verificar los requisitos que la legislacion mexicana impone a quien promueve el despacho por si mismo (Ley Aduanera, Art. 40) antes de prescindir del agente aduanal", "Gestionar el acceso a los sistemas electronicos aduaneros, directo o mediante proveedor de servicios, que el Art. 7.20.1 obliga a otorgar en condiciones no discriminatorias"]'::jsonb, '["El T-MEC respalda la auto-declaracion, pero remite a las leyes y regulaciones de cada Parte: no es una habilitacion automatica para operar sin agente aduanal en Mexico", "Los requisitos para ser agente aduanal deben ser transparentes y objetivos (Art. 7.20.2): un requisito arbitrario es impugnable con base en el Tratado"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-TMEC-7.20-AGENTES-ADUANALES'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

